async function adminShifts(){try{const j=await api('adminShifts');window._shiftRows=j.rows||[];adminShell('CA LÀM',`<div class="helper">Chỉnh cấu hình rồi bấm <b>LƯU THAY ĐỔI</b>. Ca NGÀY tính 1 công, không yêu cầu giờ vào/ra.</div><div class="shift-grid">${j.rows.map((x,i)=>{const day=(/ngày|ngay|full day/i.test(String(x.SHIFT_NAME||''))||/^SHIFT0?4$/i.test(String(x.SHIFT_ID||'')));return `<div class="shift-card ${day?'day-shift':''}" data-shift-index="${i}"><div class="shift-name"><b>${esc(x.SHIFT_NAME)}</b><small>${esc(x.SHIFT_ID)}</small></div><div class="field"><label>TÊN CA</label><input class="shift-name-input" value="${esc(x.SHIFT_NAME)}"></div><label class="select-item"><input class="shift-is-day" type="checkbox" ${day?'checked':''} onchange="toggleShiftCard(${i})"> <span>Ca ngày · 1 công · không xét giờ</span></label><div class="shift-times"><label>VÀO<input class="shift-start" type="time" value="${esc(x.START_TIME)}" ${day?'disabled':''}></label><span>→</span><label>RA<input class="shift-end" type="time" value="${esc(x.END_TIME)}" ${day?'disabled':''}></label></div><div class="shift-tolerances"><label>TRỄ (phút)<input class="shift-late" type="number" min="0" max="180" value="${day?0:esc(x.LATE_TOL_MIN??15)}" ${day?'disabled':''}></label><label>SỚM (phút)<input class="shift-early" type="number" min="0" max="180" value="${day?0:esc(x.EARLY_TOL_MIN??0)}" ${day?'disabled':''}></label></div><label class="field shift-status-field"><span>Trạng thái</span><select class="shift-status"><option value="ACTIVE" ${x.STATUS==='ACTIVE'?'selected':''}>ACTIVE</option><option value="INACTIVE" ${x.STATUS!=='ACTIVE'?'selected':''}>INACTIVE</option></select></label><button class="btn blue full" onclick="saveShiftRow(${i})">LƯU THAY ĐỔI</button></div>`}).join('')}</div><div class="section-actions no-print"><button class="btn blue" onclick="shiftForm()">+ THÊM CA</button></div>`)}catch(e){toast(e.message)}}
function toggleShiftCard(i){const c=document.querySelector('[data-shift-index="'+i+'"]');if(!c)return;const day=c.querySelector('.shift-is-day').checked;c.classList.toggle('day-shift',day);c.querySelector('.shift-start').disabled=day;c.querySelector('.shift-end').disabled=day;c.querySelector('.shift-late').disabled=day;c.querySelector('.shift-early').disabled=day;c.querySelector('.shift-status').disabled=false;if(day){c.querySelector('.shift-start').value='';c.querySelector('.shift-end').value='';c.querySelector('.shift-late').value='0';c.querySelector('.shift-early').value='0';if(!/ngày|ngay/i.test(c.querySelector('.shift-name-input').value))c.querySelector('.shift-name-input').value='NGÀY'}}
async function saveShiftRow(i){const c=document.querySelector('[data-shift-index="'+i+'"]'),old=(window._shiftRows||[])[i];if(!c||!old)return;const day=c.querySelector('.shift-is-day').checked,btn=c.querySelector('button'),p={SHIFT_ID:old.SHIFT_ID,SHIFT_NAME:c.querySelector('.shift-name-input').value.trim(),START_TIME:day?'':c.querySelector('.shift-start').value,END_TIME:day?'':c.querySelector('.shift-end').value,LATE_TOL_MIN:c.querySelector('.shift-late').value,EARLY_TOL_MIN:c.querySelector('.shift-early').value,STATUS:c.querySelector('.shift-status').value};if(!p.SHIFT_NAME)return toast('Tên ca không được để trống.');if(day&&!/ngày|ngay/i.test(p.SHIFT_NAME)&&!/^SHIFT0?4$/i.test(p.SHIFT_ID))return toast('Ca không xét giờ cần có tên NGÀY.');if(!day&&(!p.START_TIME||!p.END_TIME))return toast('Nhập đủ giờ vào/ra hoặc chọn Ca ngày.');if(btn)btn.disabled=true;try{await api('adminSaveShift',p);toast('Đã lưu cấu hình ca.');await adminShifts()}catch(e){if(btn)btn.disabled=false;toast(e.message)}}
function shiftForm(x={}){const day=(/ngày|ngay/i.test(String(x.SHIFT_NAME||''))||/^SHIFT0?4$/i.test(String(x.SHIFT_ID||'')));adminShell('THÊM CA LÀM',`<div class="card"><div class="two"><div class="field"><label>Mã ca</label><input id="sf_id" value="${esc(x.SHIFT_ID||'')}"></div><div class="field"><label>Tên ca</label><input id="sf_name" value="${esc(x.SHIFT_NAME||'')}"></div></div><label class="select-item"><input id="sf_day" type="checkbox" ${day?'checked':''} onchange="toggleShiftFormFields()"> <span>Ca ngày · tính 1 công · không yêu cầu giờ</span></label><div class="two"><div class="field"><label>Bắt đầu</label><input id="sf_start" type="time" value="${esc(x.START_TIME||'08:00')}" ${day?'disabled':''}></div><div class="field"><label>Kết thúc</label><input id="sf_end" type="time" value="${esc(x.END_TIME||'17:00')}" ${day?'disabled':''}></div></div><div class="shift-tolerances"><div class="field"><label>Cho phép TRỄ (phút)</label><input id="sf_late" type="number" min="0" max="180" value="${esc(x.LATE_TOL_MIN??15)}"></div><div class="field"><label>Cho phép SỚM (phút)</label><input id="sf_early" type="number" min="0" max="180" value="${esc(x.EARLY_TOL_MIN??0)}"></div></div><div class="field"><label>Trạng thái</label><select id="sf_status"><option value="ACTIVE">ACTIVE</option><option value="INACTIVE">INACTIVE</option></select></div><button class="btn blue full" onclick="saveShift()">LƯU CA</button></div>`);if(x.STATUS)$('sf_status').value=x.STATUS}
function toggleShiftFormFields(){const day=$('sf_day').checked;$('sf_start').disabled=day;$('sf_end').disabled=day;if(day){$('sf_start').value='';$('sf_end').value='';if(!$('sf_name').value.trim())$('sf_name').value='NGÀY'}}
