async function adminAssignments(){try{const [a,e,p,g]=await Promise.all([api('adminAssignments'),api('adminPeople'),api('adminProjects'),api('adminGroups')]);adminShell('PHÂN CÔNG',`<div class="card"><div class="two"><div class="field"><label>Ngày</label><input id="af_date" type="date" value="${localDate()}"></div><div class="field"><label>Nhóm</label><select id="af_group"><option value="">Không chọn</option>${g.rows.filter(x=>x.STATUS==='ACTIVE').map(x=>`<option value="${esc(x.GROUP_ID)}">${esc(x.GROUP_NAME)}</option>`).join('')}</select></div></div><div class="field"><label>Công trình</label><select id="af_project">${p.rows.map(x=>`<option value="${esc(x.PROJECT_ID)}">${esc(x.PROJECT_NAME)}</option>`).join('')}</select></div><div class="field"><label>Ca</label><select id="af_shift"><option value="SANG">SÁNG</option><option value="CHIEU">CHIỀU</option><option value="TOI">TỐI</option><option value="NGAY">NGÀY</option></select></div><div class="field"><label>Tên công việc</label><input id="af_task"></div><div class="field"><label>Ghi chú</label><textarea id="af_note"></textarea></div><div class="field"><label>Nhân viên được phân công</label><div class="select-list">${e.rows.filter(x=>x.STATUS==='ACTIVE').map(x=>`<label class="select-item"><input type="checkbox" name="af_emp" value="${esc(x.EMPLOYEE_ID)}"> <span>${esc(x.NAME)}</span></label>`).join('')}</div></div><button class="btn blue full" onclick="saveAssignment()">LƯU PHÂN CÔNG</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>Ngày</th><th>Nhân viên</th><th>Công trình</th><th>Ca</th><th>Công việc</th><th></th></tr></thead><tbody>${a.rows.slice().sort((p,q)=>String(q.WORK_DATE).localeCompare(String(p.WORK_DATE))).map(x=>`<tr><td>${esc(formatVNDate(x.WORK_DATE))}</td><td>${esc((x.EMPLOYEE_NAMES||[]).join(', '))}</td><td>${esc(projectName(x.PROJECT_ID))}</td><td>${esc(shiftName(x.SHIFT_ID))}</td><td>${esc(x.TASK_TITLE)}</td><td><button class="btn red" onclick="deleteAssignment('${esc(x.ASSIGNMENT_ID)}')">XÓA</button></td></tr>`).join('')}</tbody></table></div>`)}catch(e){toast(e.message)}}
async function saveAssignment(){const btn=document.querySelector('button[onclick="saveAssignment()"]'),ids=[...document.querySelectorAll('input[name="af_emp"]:checked')].map(x=>x.value);if(btn)btn.disabled=true;try{await api('adminSaveAssignment',{WORK_DATE:$('af_date').value,GROUP_ID:$('af_group').value,PROJECT_ID:$('af_project').value,SHIFT_PART:$('af_shift').value,TASK_TITLE:$('af_task').value,NOTE:$('af_note').value,EMPLOYEE_IDS:ids});toast('Đã lưu phân công.');await adminAssignments()}catch(e){if(btn)btn.disabled=false;toast(e.message)}}
