function fmt2(v){const n=Number(v||0);return Number.isFinite(n)?(Math.round((n+Number.EPSILON)*100)/100).toLocaleString('vi-VN',{minimumFractionDigits:0,maximumFractionDigits:2}):'0'}

async function runAdminDataAudit(){const area=$('dataAuditArea');if(area)area.innerHTML='<div class="card">Đang đối chiếu dữ liệu chỉ đọc…</div>';try{const j=await api('adminDataAudit');const c=j.counts||{},issues=j.issues||[];if(area)area.innerHTML=`<div class="card"><h2>KẾT QUẢ KIỂM TRA</h2><p>Phiên bản ${esc(j.version)} · ${esc(String(j.issueCount))} vấn đề phát hiện · Không thay đổi dữ liệu.</p><div class="report-summary"><span>${c.employees||0} nhân viên</span><span>${c.projects||0} công trình</span><span>${c.shifts||0} ca</span><span>${c.attendance||0} bản ghi công</span><span>${c.assignments||0} phân công</span><span>${c.notifications||0} thông báo</span></div>${issues.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Loại lỗi</th><th>Sheet / khóa</th><th>Chi tiết</th></tr></thead><tbody>${issues.map(x=>`<tr><td>${esc(x.type||'')}</td><td>${esc(x.sheet||x.key||x.assignmentId||'')}</td><td>${esc(JSON.stringify(x))}</td></tr>`).join('')}</tbody></table></div>`:'<p>Không phát hiện lỗi nhất quán theo các kiểm tra hiện có.</p>'}</div>`}catch(e){if(area)area.innerHTML=`<div class="card error-card">Không kiểm tra được: ${esc(e.message)}</div>`;toast(e.message)}}
function downloadApiTiming(){let rows=[];try{rows=JSON.parse(LS.getItem('cl_api_timing')||'[]')}catch(e){}if(!rows.length)return toast('Chưa có nhật ký tốc độ. Hãy thao tác thử các chức năng trước.');const blob=new Blob([JSON.stringify(rows,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cuatung-api-timing.json';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Đã xuất nhật ký tốc độ.')}
function projectName(id){const s=String(id||'');if(s.startsWith('OTHER:')){try{return decodeURIComponent(s.slice(6))}catch(e){return s.slice(6)}}return S.projects.find(x=>String(x.PROJECT_ID)===s)?.PROJECT_NAME||s}function shiftName(id){return S.shifts.find(x=>String(x.SHIFT_ID)===String(id))?.SHIFT_NAME||id}
function showChangePassword(force){adminShell('ĐỔI MẬT KHẨU',`<div class="card"><p>${force?'Tài khoản phải đổi mật khẩu trước khi tiếp tục.':''}</p><div class="field"><label>Mật khẩu mới</label><input id="cp1" type="password"></div><div class="field"><label>Nhập lại</label><input id="cp2" type="password"></div><button class="btn blue full" onclick="changePassword()">ĐỔI MẬT KHẨU</button></div>`)}
async function changePassword(){if($('cp1').value!==$('cp2').value)return toast('Hai mật khẩu không khớp.');try{await api('changePassword',{newPassword:$('cp1').value});await bootstrap();showHome()}catch(e){toast(e.message)}}
async function resetAndSync(){const b=$('topReset');if(b){b.disabled=true;b.classList.add('busy')}try{if(navigator.onLine&&token){await syncQueue();await bootstrap();if(screen==='attendance'||screen==='otherAttendance')renderAttendance(screen==='otherAttendance',false);else if(screen==='userHome'||screen==='adminHome')showHome();await refreshUnread();toast('Đã tải lại trạng thái và kiểm tra hàng đợi đồng bộ.')}else{const snap=readSnapshot();if(snap)applyBootstrap(snap.data);toast('Đang ngoại tuyến: giữ nguyên dữ liệu cục bộ, sẽ đồng bộ khi có mạng.')}}catch(e){toast('Chưa làm mới được: '+e.message)}finally{if(b){b.disabled=false;b.classList.remove('busy')}}}
function requestLogout(){$('modalTitle').textContent='ĐĂNG XUẤT';$('modalText').textContent='Bạn có chắc muốn đăng xuất khỏi tài khoản này?';$('modalCancel').textContent='HỦY';$('modalOk').textContent='ĐĂNG XUẤT';$('modal').classList.remove('hidden');$('modalOk').onclick=async()=>{ $('modal').classList.add('hidden'); await doLogout() };$('modalCancel').onclick=()=>{$('modal').classList.add('hidden')}} 
async function doLogout(){pushLogout();const revoke=token?api('logout').catch(()=>null):Promise.resolve(null);clearSession();renderLogin('Đã đăng xuất khỏi thiết bị.');await Promise.race([revoke,new Promise(resolve=>setTimeout(resolve,350))])}
async function restore(){
  renderLogin();if(!token||!me)return;const snap=readSnapshot();
  if(snap&&snap.data)applyBootstrap(snap.data);
  showHome();showUnread();
  bootstrap().then(()=>{if(screen==='userHome'||screen==='adminHome')showHome();showUnread();scheduleSync(200)}).catch(e=>{if(/phiên đăng nhập|không hợp lệ|hết hạn/i.test(e.message)){clearSession();renderLogin()}else{setNet(false);toast('Đang sử dụng dữ liệu đã lưu. Khi có mạng sẽ cập nhật.')}})
}
function start(){if(!window.__clEligibilityTimer)window.__clEligibilityTimer=setInterval(()=>{if(!token||document.hidden)return;if(isAttendanceScreen()&&!attendanceBusy)refreshAttendanceEligibility();else if(screen==='userHome')renderHomeToday()},5000);const n=$('netState');if(n){n.textContent='SẴN SÀNG';n.classList.remove('offline');n.classList.add('ready')}restore();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{});scheduleSync(800);setTimeout(refreshUnread,1500);setInterval(()=>{if(token&&navigator.onLine)refreshUnread()},30000);setInterval(()=>{if(token&&navigator.onLine&&overlayRead().length)syncQueue()},20000);window.addEventListener('focus',()=>{if(token&&navigator.onLine)scheduleSync(300)});setTimeout(()=>{try{SS.removeItem('cl_vreload')}catch(_){}},10000)}
// ===== V11.0.5 UI: home, attendance (nearest project), approval, leave, history =====
const STATUS_VN={APPROVED:['Đã duyệt','ok'],PENDING:['Chờ duyệt','warn'],REJECTED:['Từ chối','bad'],'CHỜ ĐỒNG BỘ':['Chờ đồng bộ','warn']};
function statusBadge(s){const x=STATUS_VN[String(s||'')]||[String(s||''),''];return `<span class="badge ${x[1]}">${esc(x[0])}</span>`}
function fmtDist(m){if(m===null||m===undefined||!Number.isFinite(Number(m)))return '';m=Number(m);return m<1000?Math.round(m)+' m':(m/1000).toLocaleString('vi-VN',{maximumFractionDigits:1})+' km'}
function weekdayVN(date){const d=new Date(String(date).slice(0,10)+'T12:00:00+07:00');return isNaN(d)?'':['Chủ nhật','Thứ Hai','Thứ Ba','Thứ Tư','Thứ Năm','Thứ Sáu','Thứ Bảy'][d.getUTCDay()]}
function shiftLabel(sh){return sh?`${sh.SHIFT_NAME}${sh.START_TIME&&sh.END_TIME?' · '+String(sh.START_TIME).slice(0,5)+'–'+String(sh.END_TIME).slice(0,5):''}`:''}
function gpsLimit(p,acc){return Number(p.RADIUS_M||100)+Math.min(Math.max(Number(acc)||0,0),50)}
function normVN(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d')}
function menu(i,t,s,fn,badge){return `<button class="menu-card" onclick="${fn}"><span class="ico">${i}</span>${t}<small>${s}</small>${badge?`<span class="menu-badge">${badge>99?'99+':badge}</span>`:''}</button>`}

// ---------- GPS → UI ----------
let gpsUiTimer=null;
function onGpsUpdate(){renderGpsLine();clearTimeout(gpsUiTimer);gpsUiTimer=setTimeout(()=>{if(attendanceBusy)return;if(isAttendanceScreen())renderAttendanceShiftState();else if(screen==='userHome')renderHomeToday()},250)}
function projectDistances(){const f=gpsFresh(300000,1000);return S.projects.map(p=>{const lat=Number(p.LAT),lng=Number(p.LNG),has=!!f&&Number.isFinite(lat)&&Number.isFinite(lng)&&!(lat===0&&lng===0);const d=has?geo(f.latitude,f.longitude,lat,lng):null;return{p,d,inside:d!==null&&d<=gpsLimit(p,f&&f.accuracy)}})}
function nearestProject(){return projectDistances().filter(x=>x.d!==null).sort((a,b)=>a.d-b.d)[0]||null}
// kept for older call sites
function updateNearestProject(){onGpsUpdate()}
function selectNearestProject(){onGpsUpdate()}

// ---------- Employee home ----------
function renderUserHome(){screen='userHome';const unread=(S.unread||[]).filter(n=>within5Days(n)).length,today=localDate(),work=(S.assignments||[]).filter(a=>String(a.WORK_DATE||'').slice(0,10)>=today||(a.CREATED_AT&&Date.now()-new Date(a.CREATED_AT).getTime()<86400000)).length;page(`<section class="screen wrap"><div class="home-head"><div><div class="user-name">${esc(me?.NAME||'')}</div><div class="user-role">NHÂN VIÊN</div></div><div class="icon-actions"><button class="icon-btn has-badge" aria-label="Thông báo" onclick="renderNotifications()">🔔${unread?`<span class="dot">${unread}</span>`:''}</button></div></div><div id="installBanner" class="push-banner install hidden"></div>${pushBannerHTML()}<div id="todayCard" class="today-card"></div><div class="grid user-grid">${menu('📊','THỐNG KÊ','Công / phép theo tháng','renderStats()')}${menu('📋','CÔNG VIỆC','Phân công của tôi','renderWork()',work)}${menu('📝','BÁO PHÉP','Nghỉ theo ngày / ca','renderLeave()')}${menu('🕘','LỊCH SỬ','Các lượt chấm công','renderHistory()')}</div></section>`);renderHomeToday();renderInstallBanner();renderPushBanner();runShortcut()}
function renderHomeToday(){const box=$('todayCard');if(!box)return;refreshAttendanceEligibility(false);const sh=currentShift(),state=S.attendanceShift,date=localDate();let status='',btn='',cls='',near='';if(!sh){status='Chưa có ca làm phù hợp lúc này.';btn=`<button class="btn light full" onclick="renderAttendance()">MỞ CHẤM CÔNG</button>`}else if(isDayShift(sh)){status='Ca NGÀY do Admin ghi nhận.'}else{const att=attendanceForShift(sh.SHIFT_ID,sh.SHIFT_WORK_DATE||date),open=!!(att&&att.CHECKIN_TIME&&!att.CHECKOUT_TIME),done=!!(att&&att.CHECKOUT_TIME),pending=!!(att&&(att._local||att._pendingCheckout));if(done){cls='done';status=`✓ Đã xong ca ${esc(sh.SHIFT_NAME)}${pending?' · chờ đồng bộ':String(att.STATUS)==='PENDING'?' · chờ duyệt':''}`;btn=`<button class="btn light full" onclick="renderAttendance()">XEM CHẤM CÔNG</button>`}else if(open){cls='open';status=`Đang làm tại <b>${esc(projectName(att.PROJECT_ID))}</b><br><small>Vào lúc ${esc(clockText(att.CHECKIN_TIME))}${pending?' · chờ đồng bộ':''}</small>`;btn=`<button class="btn red full big" onclick="renderAttendance()">RA CA</button>`}else{const ok=state&&state.eligible;status=ok?'Bạn chưa VÀO CA.':esc(state?.reason||'Chưa đến giờ chấm ca.');const n=nearestProject();if(n)near=`<div class="near ${n.inside?'in':''}">📍 Gần nhất: <b>${esc(n.p.PROJECT_NAME)}</b> · ${fmtDist(n.d)}${n.inside?' · trong khu vực':''}</div>`;btn=`<button class="btn green full big" ${ok?'':'disabled'} onclick="renderAttendance()">VÀO CA</button>`}}box.className='today-card '+cls;box.innerHTML=`<div class="today-top"><span>${esc(weekdayVN(date))}, ${esc(formatVNDate(date))}</span>${sh&&!isDayShift(sh)?`<b>CA ${esc(shiftLabel(sh))}</b>`:''}</div><p class="today-status">${status}</p>${near}${btn}`}

// ---------- Attendance screen with nearest-project picker ----------
let selProject='',projectOrder=[],pickerExpanded=false,pickerQuery='';
function renderAttendance(isOther=false,refresh=true){const same=isAttendanceScreen(),prevName=same?($('otherProjectName')?.value||''):'';if(!same){projectTouched=false;pickerExpanded=false;pickerQuery='';projectOrder=[];if(isOther){selProject='__OTHER__';projectTouched=true}}screen='attendance';const sh=currentShift(),date=localDate();page(`<section class="screen wrap att-screen"><button class="back" onclick="goBack()">← QUAY LẠI</button><div class="att-head"><div><small>${esc(weekdayVN(date))}, ${esc(formatVNDate(date))}</small><h1 class="screen-title">CHẤM CÔNG</h1></div><span class="status-pill ok">${esc(sh?'CA '+shiftLabel(sh):'Chưa có ca')}</span></div><div class="card att-card"><div id="openInfo"></div><div id="pickWrap"><div class="pick-head"><b>CHỌN CÔNG TRÌNH</b><div id="gpsLine" class="gps-line"></div></div>${S.projects.length>6?`<input id="projSearch" class="proj-search" type="search" placeholder="Tìm công trình…" autocomplete="off" value="${esc(pickerQuery)}">`:''}<div id="projectPicker" class="proj-list" role="radiogroup" aria-label="Công trình"></div><div id="otherWrap" class="field hidden"><label for="otherProjectName">Tên công trình (ngoài danh sách)</label><input id="otherProjectName" maxlength="160" placeholder="Nhập tên công trình" value="${esc(prevName)}"></div></div><div id="gpsWarn"></div><div id="attendanceActionArea"></div><p class="helper" id="shiftHint"></p></div></section>`);
  const picker=$('projectPicker');picker.addEventListener('click',e=>{const b=e.target.closest('[data-pid],[data-more]');if(!b)return;if(b.dataset.more){pickerExpanded=true;renderAttendanceShiftState();return}selProject=b.dataset.pid;projectTouched=true;renderAttendanceShiftState();if(selProject==='__OTHER__')setTimeout(()=>$('otherProjectName')?.focus(),50)});
  const qs=$('projSearch');if(qs)qs.addEventListener('input',()=>{pickerQuery=qs.value;renderProjectPicker()});
  const on=$('otherProjectName');if(on)on.addEventListener('input',()=>renderActionButton());
  renderAttendanceShiftState();gpsWatch();renderGpsLine();
  if(refresh&&navigator.onLine&&Date.now()-lastBootAt>15000)bootstrap().then(()=>{if(isAttendanceScreen())renderAttendanceShiftState()}).catch(()=>{})}
function renderOtherAttendance(){selProject='__OTHER__';renderAttendance(true)}
function autoSelectProject(list){if(projectTouched)return;const n=list.filter(x=>x.d!==null).sort((a,b)=>a.d-b.d)[0];if(n&&n.inside){selProject=n.p.PROJECT_ID;return}if(selProject&&S.projects.some(p=>p.PROJECT_ID===selProject))return;const last=LS.getItem('cl_last_project');selProject=last&&S.projects.some(p=>p.PROJECT_ID===last)?last:''}
function renderProjectPicker(){const box=$('projectPicker');if(!box)return;const list=projectDistances(),byId={};list.forEach(x=>byId[x.p.PROJECT_ID]=x);autoSelectProject(list);const last=LS.getItem('cl_last_project');
  // Re-sort only until the employee touches the list, so items never jump under their finger.
  if(!projectTouched||!projectOrder.length)projectOrder=list.slice().sort((a,b)=>(a.d===null)-(b.d===null)||(a.d!==null&&b.d!==null?a.d-b.d:0)||(b.p.PROJECT_ID===last)-(a.p.PROJECT_ID===last)||String(a.p.PROJECT_NAME).localeCompare(String(b.p.PROJECT_NAME),'vi')).map(x=>x.p.PROJECT_ID);
  const ids=projectOrder.filter(id=>byId[id]).concat(list.map(x=>x.p.PROJECT_ID).filter(id=>!projectOrder.includes(id)));
  const nearestId=ids.find(id=>byId[id].d!==null),q=normVN(pickerQuery.trim());
  let shown=q?ids.filter(id=>normVN(byId[id].p.PROJECT_NAME+' '+(byId[id].p.ADDRESS||'')).includes(q)):pickerExpanded?ids:ids.slice(0,4);
  if(!q&&selProject&&byId[selProject]&&!shown.includes(selProject))shown=shown.concat(selProject);
  const item=id=>{const x=byId[id],p=x.p,sel=selProject===id,meta=x.d===null?esc(p.ADDRESS||'Chưa xác định khoảng cách'):`${fmtDist(x.d)} · ${x.inside?'<span class="in">Trong khu vực</span>':`<span class="out">Ngoài bán kính ${Number(p.RADIUS_M||100)} m</span>`}`;return `<button type="button" class="proj-opt${sel?' sel':''}${id===nearestId?' nearest':''}" role="radio" aria-checked="${sel}" data-pid="${esc(id)}"><span class="radio"></span><span class="proj-txt"><b>${esc(p.PROJECT_NAME)}</b><small>${meta}</small></span>${id===nearestId?'<span class="tag">GẦN NHẤT</span>':''}</button>`};
  const more=!q&&!pickerExpanded&&ids.length>shown.length?`<button type="button" class="proj-more" data-more="1">Xem tất cả ${ids.length} công trình</button>`:'';
  const other=`<button type="button" class="proj-opt other${selProject==='__OTHER__'?' sel':''}" role="radio" aria-checked="${selProject==='__OTHER__'}" data-pid="__OTHER__"><span class="radio"></span><span class="proj-txt"><b>Công trình khác</b><small>Không có trong danh sách – nhập tên</small></span></button>`;
  box.innerHTML=(S.projects.length?'':'<p class="helper">Chưa có công trình đang hoạt động.</p>')+(shown.length?shown.map(item).join(''):(q?'<p class="helper">Không tìm thấy công trình phù hợp.</p>':''))+more+other;
  const ow=$('otherWrap');if(ow)ow.classList.toggle('hidden',selProject!=='__OTHER__')}
function renderProjectWarning(pid,label){const w=$('gpsWarn');if(!w)return;if(!pid){w.innerHTML='';return}if(pid==='__OTHER__'||String(pid).startsWith('OTHER:')){w.innerHTML='<div class="warn-box info">Công trình ngoài danh sách: lượt chấm công sẽ được Admin kiểm tra.</div>';return}const p=S.projects.find(x=>String(x.PROJECT_ID)===String(pid)),f=gpsFresh(300000,1000);if(!p||!f||(Number(p.LAT)===0&&Number(p.LNG)===0)){w.innerHTML='';return}const d=geo(f.latitude,f.longitude,Number(p.LAT),Number(p.LNG));if(!Number.isFinite(d)||d<=gpsLimit(p,f.accuracy)){w.innerHTML='';return}w.innerHTML=`<div class="warn-box">⚠ Bạn đang cách <b>${esc(p.PROJECT_NAME)}</b> khoảng <b>${fmtDist(d)}</b> (cho phép ${Number(p.RADIUS_M||100)} m).<br>Vẫn ${label} được – lượt này sẽ chờ Admin kiểm tra.</div>`}
function selectedProjectName(){if(selProject==='__OTHER__')return ($('otherProjectName')?.value||'').trim();return S.projects.find(p=>p.PROJECT_ID===selProject)?.PROJECT_NAME||''}
function renderActionButton(){const area=$('attendanceActionArea');if(!area||!$('pickWrap')||$('pickWrap').classList.contains('hidden'))return;const state=S.attendanceShift,eligible=!!(state&&state.eligible),name=selectedProjectName(),ready=eligible&&!!selProject&&(selProject!=='__OTHER__'||!!name);area.innerHTML=`<button class="btn green full attendance-btn big" ${ready?'':'disabled'} onclick="checkin()">VÀO CA${name?`<small>${esc(name)}</small>`:''}</button>`;const hint=$('shiftHint');if(hint)hint.textContent=!eligible?(state?.reason||'Chưa đến giờ chấm ca.'):!selProject?'Chọn công trình để VÀO CA.':selProject==='__OTHER__'&&!name?'Nhập tên công trình.':'';renderProjectWarning(selProject,'VÀO CA')}
function renderAttendanceShiftState(){const area=$('attendanceActionArea');if(!area)return;refreshAttendanceEligibility(false);const sh=currentShift(),pick=$('pickWrap'),info=$('openInfo'),hint=$('shiftHint');const showPick=v=>{if(pick)pick.classList.toggle('hidden',!v)};if(info)info.innerHTML='';if(hint)hint.textContent='';if(!sh){showPick(false);renderProjectWarning('');area.innerHTML='<p class="helper">Chưa có ca SÁNG/CHIỀU/TỐI phù hợp lúc này. Liên hệ Admin nếu cần.</p>';return}if(isDayShift(sh)){showPick(false);area.innerHTML='<p class="helper">Ca NGÀY do Admin ghi nhận; nhân viên chấm theo ca SÁNG/CHIỀU/TỐI.</p>';return}
  const att=attendanceForShift(sh.SHIFT_ID,sh.SHIFT_WORK_DATE||localDate()),open=!!(att&&att.CHECKIN_TIME&&!att.CHECKOUT_TIME),done=!!(att&&(att.CHECKOUT_TIME||String(att.STATUS)==='APPROVED'&&!att.CHECKIN_TIME)),pending=!!(att&&(att._local||att._pendingCheckout));
  if(done){showPick(false);renderProjectWarning('');area.innerHTML=`<div class="success-card"><div class="success-icon">✓</div><h2>ĐÃ XONG CA ${esc(sh.SHIFT_NAME)}</h2><p>${esc(projectName(att.PROJECT_ID))} · ${esc(clockText(att.CHECKIN_TIME)||'—')} → ${esc(clockText(att.CHECKOUT_TIME)||'—')}</p><p>${pending?'Đã lưu trên máy – đang chờ đồng bộ.':String(att.STATUS)==='PENDING'?'Chờ Admin duyệt.':String(att.STATUS)==='APPROVED'?'Đã được duyệt.':''}</p></div>`;return}
  if(open){showPick(false);if(info)info.innerHTML=`<div class="open-info"><span>ĐANG LÀM TẠI</span><b>${esc(projectName(att.PROJECT_ID))}</b><small>Vào lúc ${esc(clockText(att.CHECKIN_TIME)||'—')}${pending?' · chờ đồng bộ':String(att.STATUS)==='PENDING'?' · chờ duyệt':''}</small></div>`;area.innerHTML='<button class="btn red full attendance-btn big" onclick="checkout()">RA CA</button>';renderProjectWarning(att.PROJECT_ID,'RA CA');return}
  showPick(true);renderProjectPicker();renderActionButton()}
function checkin(){const custom=selProject==='__OTHER__',projectName=custom?String($('otherProjectName')?.value||'').trim():'';if(custom&&!projectName){$('otherProjectName')?.focus();return toast('Nhập tên công trình.')}const projectId=custom?'OTHER:'+encodeURIComponent(projectName):String(selProject||'');if(!projectId)return toast('Chọn công trình trước khi VÀO CA.');const sh=currentShift();if(!sh)return toast('Chưa đến khung giờ chấm ca hoặc chưa có ca hoạt động.');if(S.attendanceShift&&!S.attendanceShift.eligible)return toast(S.attendanceShift.reason||'Chưa đến giờ chấm ca.');if(!custom)try{LS.setItem('cl_last_project',projectId)}catch(_){}return runAttendance('CHECKIN',{projectId,projectName,custom,shiftId:sh.SHIFT_ID,workDate:sh.SHIFT_WORK_DATE||localDate()})}
function checkinOther(){selProject='__OTHER__';return checkin()}

// ---------- Admin home ----------
function renderAdminHome(){screen='adminHome';const pa=Number(S.pending?.attendance||0),pl=Number(S.pending?.leave||0);page(`<section class="screen wrap"><div class="home-head"><div><div class="user-name">${esc(me?.NAME||'')}</div><div class="user-role">QUẢN TRỊ VIÊN</div></div><div class="icon-actions"><button class="icon-btn has-badge" aria-label="Thông báo" onclick="renderNotifications()">🔔${(S.unread||[]).filter(n=>within5Days(n)).length?`<span class="dot">${(S.unread||[]).filter(n=>within5Days(n)).length}</span>`:''}</button></div></div><div id="installBanner" class="push-banner install hidden"></div>${pushBannerHTML()}<div class="pending-strip"><button class="pend ${pa?'hot':''}" onclick="adminAttendance()"><b>${pa}</b><span>Công chờ duyệt</span></button><button class="pend ${pl?'hot':''}" onclick="adminLeave()"><b>${pl}</b><span>Phép chờ duyệt</span></button></div><h3 class="menu-group">HẰNG NGÀY</h3><div class="admin-menu">${menu('✅','DUYỆT CÔNG','Lượt chờ duyệt','adminAttendance()',pa)}${menu('📝','NGHỈ PHÉP','Đơn chờ duyệt','adminLeave()',pl)}${menu('📄','BÁO CÁO','Ngày / tháng / công trình','adminReports()')}${menu('📋','PHÂN CÔNG','Nhân viên / công trình / ca','adminAssignments()')}${menu('🔔','THÔNG BÁO','Gửi / lịch sử','adminNotifications()')}</div><h3 class="menu-group">DANH MỤC &amp; CẤU HÌNH</h3><div class="admin-menu">${menu('👥','NHÂN VIÊN','Thêm / sửa / khóa','adminEmployees()')}${menu('📍','CÔNG TRÌNH','Tọa độ / bán kính','adminProjects()')}${menu('⏱','CA LÀM','Giờ ca / dung sai','adminShifts()')}${menu('👨‍👩‍👧','NHÓM','Nhóm làm việc','adminGroups()')}${menu('📈','TỔNG QUAN','Số liệu hệ thống','adminDashboard()')}${menu('🛡','NHẬT KÝ','Audit / kiểm tra','adminLogs()')}</div></section>`);renderInstallBanner();renderPushBanner();runShortcut();if(navigator.onLine&&token&&Date.now()-lastBootAt>30000)bootstrap().then(()=>{if(screen==='adminHome')renderAdminHome()}).catch(()=>{})}

// ---------- Approval (redesigned) ----------
const AP={rows:[],filter:'ALL',sel:new Set(),busy:new Set(),viewIds:[]};let apBuf=[],apTimer=null;
const AP_LABELS={ALL:'Tất cả',CLEAN:'Không cảnh báo',GPS:'Sai vị trí',NOGPS:'Không GPS',TIME:'Trễ / sớm',OPEN:'Chưa ra ca',OTHER:'CT ngoài DS'};
const AP_SERIOUS=['GPS','NOGPS','TIME','DEVICE','OTHER'];
function minsBetween(a,b){const m=t=>{const p=String(t||'').split(':').map(Number);return p.length===2&&p.every(Number.isFinite)?p[0]*60+p[1]:null};const x=m(a),y=m(b);if(x===null||y===null)return '';let d=y-x;if(d<0)d+=1440;return d>0&&d<720?' '+d+' phút':''}
function apFlags(x){const f=[],mapUrl=(la,ln)=>la!==null&&ln!==null&&la!==undefined&&ln!==undefined?`https://maps.google.com/?q=${la},${ln}`:'';
  if(x.CHECKIN_GPS_STATUS==='OUTSIDE')f.push({k:'GPS',cls:'bad',t:`Vào ca cách CT ${fmtDist(x.CHECKIN_DISTANCE_M)}${x.RADIUS_M?` (cho phép ${x.RADIUS_M} m)`:''}`,map:mapUrl(x.CHECKIN_LAT,x.CHECKIN_LNG)});
  if(x.CHECKOUT_GPS_STATUS==='OUTSIDE')f.push({k:'GPS',cls:'bad',t:`Ra ca cách CT ${fmtDist(x.CHECKOUT_DISTANCE_M)}${x.RADIUS_M?` (cho phép ${x.RADIUS_M} m)`:''}`,map:mapUrl(x.CHECKOUT_LAT,x.CHECKOUT_LNG)});
  const other=String(x.PROJECT_ID||'').startsWith('OTHER:');if(other)f.push({k:'OTHER',cls:'info',t:'Công trình ngoài danh sách',map:mapUrl(x.CHECKIN_LAT,x.CHECKIN_LNG)});
  const noIn=x.CHECKIN_HHMM&&(!x.CHECKIN_GPS_STATUS||x.CHECKIN_GPS_STATUS==='UNKNOWN'),noOut=x.CHECKOUT_HHMM&&(!x.CHECKOUT_GPS_STATUS||x.CHECKOUT_GPS_STATUS==='UNKNOWN');if(noIn||noOut)f.push({k:'NOGPS',cls:'warn',t:'Không có GPS'+(noIn&&noOut?'':noIn?' lúc vào':' lúc ra')});
  if(x.CHECKIN_TIME_WARNING==='YES')f.push({k:'TIME',cls:'warn',t:'Vào trễ'+minsBetween(x.SHIFT_START,x.CHECKIN_HHMM)});
  if(x.CHECKOUT_TIME_WARNING==='YES')f.push({k:'TIME',cls:'warn',t:'Ra sớm'+minsBetween(x.CHECKOUT_HHMM,x.SHIFT_END)});
  if(x.DEVICE_TIME_WARNING==='YES')f.push({k:'DEVICE',cls:'warn',t:'Giờ điện thoại lệch'});
  if(!x.CHECKOUT_HHMM)f.push({k:'OPEN',cls:'info',t:'Chưa ra ca'});
  if(x.OFFLINE_CHECKIN==='YES'||x.OFFLINE_CHECKOUT==='YES')f.push({k:'OFFLINE',cls:'info',t:'Chấm khi mất mạng'});
  return f}
async function adminAttendance(){adminShell('DUYỆT CÔNG',`<div id="apTop" class="ap-top"></div><div id="apList" class="ap-list"><div class="loading-inline">Đang tải danh sách chờ duyệt…</div></div><div id="apBar" class="ap-bar hidden"></div>`);const root=document.querySelector('#app .screen');root.addEventListener('click',apClick);root.addEventListener('change',e=>{const id=e.target&&e.target.dataset&&e.target.dataset.sel;if(!id)return;e.target.checked?AP.sel.add(id):AP.sel.delete(id);renderApproval()});try{const j=await api('adminAttendance');AP.rows=j.rows||[];AP.sel.clear();AP.busy.clear();S.pending=Object.assign({},S.pending||{},{attendance:AP.rows.length},typeof j.pendingLeave==='number'?{leave:j.pendingLeave}:{});renderApproval()}catch(e){const l=$('apList');if(l)l.innerHTML=`<div class="error-card">${esc(e.message)} <button class="btn light" onclick="adminAttendance()">THỬ LẠI</button></div>`}}
function renderApproval(){const top=$('apTop'),list=$('apList');if(!list)return;const rows=AP.rows.filter(x=>!AP.busy.has(String(x.ATTENDANCE_ID))),items=rows.map(x=>({x,f:apFlags(x)})),counts={ALL:items.length,CLEAN:0,GPS:0,NOGPS:0,TIME:0,OPEN:0,OTHER:0};
  items.forEach(({f})=>{const ks=new Set(f.map(z=>z.k));if(!AP_SERIOUS.some(k=>ks.has(k)))counts.CLEAN++;['GPS','NOGPS','TIME','OPEN','OTHER'].forEach(k=>{if(ks.has(k))counts[k]++})});
  if(AP.filter!=='ALL'&&!counts[AP.filter])AP.filter='ALL';
  const view=items.filter(({f})=>AP.filter==='ALL'||(AP.filter==='CLEAN'?!f.some(z=>AP_SERIOUS.includes(z.k)):f.some(z=>z.k===AP.filter)));AP.viewIds=view.map(v=>String(v.x.ATTENDANCE_ID));
  [...AP.sel].forEach(id=>{if(!AP.viewIds.includes(id))AP.sel.delete(id)});
  const allSel=view.length>0&&AP.viewIds.every(id=>AP.sel.has(id));
  top.innerHTML=rows.length?`<p class="ap-count"><b>${rows.length}</b> lượt chờ duyệt</p><div class="chips-row">${Object.keys(AP_LABELS).filter(k=>k==='ALL'||counts[k]).map(k=>`<button type="button" class="chip-f${AP.filter===k?' on':''}" data-f="${k}">${AP_LABELS[k]} <span>${counts[k]}</span></button>`).join('')}</div>${view.length>1?`<label class="sel-all"><input type="checkbox" data-selall="1" ${allSel?'checked':''}> Chọn tất cả ${view.length} lượt đang hiển thị</label>`:''}`:'';
  let html='',last='';view.forEach(({x,f})=>{if(x.WORK_DATE!==last){last=x.WORK_DATE;html+=`<h3 class="ap-date">${esc(weekdayVN(x.WORK_DATE))}, ${esc(formatVNDate(x.WORK_DATE))}</h3>`}html+=apCard(x,f)});
  list.innerHTML=html||(rows.length?'<div class="empty">Không có lượt nào trong bộ lọc này.</div>':'<div class="empty big">✓ Đã duyệt hết. Không còn lượt chờ duyệt.</div>');
  renderApBar()}
function apCard(x,f){const id=esc(x.ATTENDANCE_ID),sel=AP.sel.has(String(x.ATTENDANCE_ID)),h=Number(x.WORK_HOURS||0);return `<article class="ap-card${sel?' sel':''}${f.some(z=>z.cls==='bad')?' has-bad':''}" data-card="${id}"><label class="ap-check" aria-label="Chọn"><input type="checkbox" data-sel="${id}" ${sel?'checked':''}></label><div class="ap-body"><div class="ap-row1"><b class="ap-name">${esc(x.EMPLOYEE_NAME)}</b><span class="ap-shift">${esc(x.SHIFT_NAME||'')}${x.SHIFT_START?` ${esc(x.SHIFT_START)}–${esc(x.SHIFT_END)}`:''}</span></div><div class="ap-proj">${esc(x.PROJECT_NAME||projectName(x.PROJECT_ID))}</div><div class="ap-time"><span>Vào <b>${esc(x.CHECKIN_HHMM||'—')}</b></span><span>Ra <b>${esc(x.CHECKOUT_HHMM||'—')}</b></span>${h>=0.01?`<span>${fmt2(h)} giờ</span>`:''}</div><div class="ap-flags">${f.length?f.map(z=>`<span class="flag ${z.cls}">${esc(z.t)}${z.map?` <a href="${esc(z.map)}" target="_blank" rel="noopener">Xem bản đồ</a>`:''}</span>`).join(''):'<span class="flag ok">✓ Không có cảnh báo</span>'}</div><div class="ap-actions"><button type="button" class="btn ghost-red" data-act="REJECTED" data-id="${id}">Từ chối</button><button type="button" class="btn green" data-act="APPROVED" data-id="${id}">✓ Duyệt</button></div></div></article>`}
function renderApBar(){const bar=$('apBar');if(!bar)return;const n=AP.sel.size;bar.classList.toggle('hidden',!n);bar.innerHTML=n?`<span>Đã chọn <b>${n}</b></span><button type="button" class="btn ghost-red" data-bulk="REJECTED">Từ chối</button><button type="button" class="btn green" data-bulk="APPROVED">✓ Duyệt ${n}</button>`:''}
function apClick(e){const t=e.target.closest('[data-f],[data-selall],[data-act],[data-bulk]');if(!t)return;if(t.dataset.f){AP.filter=t.dataset.f;AP.sel.clear();renderApproval();return}if(t.dataset.selall){const all=AP.viewIds.every(id=>AP.sel.has(id));AP.viewIds.forEach(id=>all?AP.sel.delete(id):AP.sel.add(id));renderApproval();return}if(t.dataset.act){decideAttendance([t.dataset.id],t.dataset.act);return}if(t.dataset.bulk){const ids=[...AP.sel];if(!ids.length)return;if(t.dataset.bulk==='APPROVED'&&ids.length>1)return confirmBox('Duyệt '+ids.length+' lượt chấm công đã chọn?','DUYỆT '+ids.length,()=>decideAttendance(ids,'APPROVED'));decideAttendance(ids,t.dataset.bulk)}}
function decideAttendance(ids,status){if(status==='REJECTED')return askRejectReason(ids.length,reason=>commitDecision(ids,status,reason));commitDecision(ids,status,'')}
// Optimistic: the card disappears immediately; taps within 0.4 s are sent as one batch request.
function commitDecision(ids,status,reason){ids=ids.map(String);ids.forEach(id=>{AP.busy.add(id);AP.sel.delete(id);const c=document.querySelector(`[data-card="${CSS.escape(id)}"]`);if(c)c.classList.add('leaving')});setTimeout(renderApproval,200);const k=status+'|'+reason;let b=apBuf.find(x=>x.k===k);if(!b){b={k,status,reason,ids:[]};apBuf.push(b)}b.ids.push(...ids);clearTimeout(apTimer);apTimer=setTimeout(flushDecisions,400)}
async function flushDecisions(){const batches=apBuf;apBuf=[];for(const b of batches){try{const r=await api('approveAttendanceBatch',{ids:b.ids,STATUS:b.status,REJECT_REASON:b.reason});const res=r.results||[],okIds=new Set(res.filter(x=>x.ok).map(x=>String(x.id))),bad=res.filter(x=>!x.ok);AP.rows=AP.rows.filter(x=>!okIds.has(String(x.ATTENDANCE_ID)));bad.forEach(x=>AP.busy.delete(String(x.id)));if(typeof r.pendingAttendance==='number')S.pending=Object.assign({},S.pending||{},{attendance:r.pendingAttendance});toast(bad.length?(bad.length+' lượt chưa xử lý được: '+bad[0].error):((b.status==='APPROVED'?'Đã duyệt ':'Đã từ chối ')+okIds.size+' lượt.'))}catch(e){b.ids.forEach(id=>AP.busy.delete(id));toast('Chưa lưu được: '+e.message+' Các lượt đã hiện lại để thử lại.')}}if(screen==='admin:DUYỆT CÔNG')renderApproval()}
function askRejectReason(n,cb){const reasons=['Sai công trình','Không có mặt tại công trình','Chấm hộ','Trùng ca'];$('modalTitle').textContent='TỪ CHỐI '+n+' LƯỢT';$('modalText').innerHTML=`<span class="reason-chips">${reasons.map(r=>`<button type="button" class="chip-f" data-reason="${esc(r)}">${esc(r)}</button>`).join('')}</span><textarea id="rejReason" class="reason-input" maxlength="300" placeholder="Lý do (không bắt buộc) – nhân viên sẽ thấy lý do này"></textarea>`;$('modalText').querySelectorAll('[data-reason]').forEach(b=>b.onclick=()=>{$('rejReason').value=b.dataset.reason});$('modalOk').textContent='TỪ CHỐI';$('modalCancel').textContent='HỦY';$('modal').classList.remove('hidden');let used=false;$('modalOk').onclick=()=>{if(used)return;used=true;const r=String($('rejReason')?.value||'').trim();$('modal').classList.add('hidden');cb(r)};$('modalCancel').onclick=()=>{$('modal').classList.add('hidden')}}
async function approveAttendance(id,status){decideAttendance([id],status)}

// ---------- Leave approval (grouped per request) ----------
const LV={rows:[],busy:new Set()};
async function adminLeave(){adminShell('NGHỈ PHÉP',`<div id="lvList" class="ap-list"><div class="loading-inline">Đang tải đơn nghỉ phép…</div></div>`);document.querySelector('#app .screen').addEventListener('click',e=>{const t=e.target.closest('[data-lv]');if(!t)return;const ids=t.dataset.ids.split(',');if(t.dataset.lv==='REJECTED')return confirmBox('Từ chối đơn nghỉ phép này?','TỪ CHỐI',()=>leaveDecision(ids,'REJECTED'));leaveDecision(ids,'APPROVED')});try{const j=await api('adminLeave',{STATUS:'PENDING'});LV.rows=j.rows||[];LV.busy.clear();S.pending=Object.assign({},S.pending||{},{leave:LV.rows.length});renderLeaveApproval()}catch(e){const l=$('lvList');if(l)l.innerHTML=`<div class="error-card">${esc(e.message)} <button class="btn light" onclick="adminLeave()">THỬ LẠI</button></div>`}}
function renderLeaveApproval(){const l=$('lvList');if(!l)return;const groups=[],idx={};LV.rows.filter(x=>!LV.busy.has(String(x.LEAVE_ID))).forEach(x=>{const k=[x.EMPLOYEE_ID,x.SHIFT||x.TYPE,x.REASON,String(x.CREATED_AT||'').slice(0,16)].join('|');if(!idx[k]){idx[k]={x,dates:[],ids:[]};groups.push(idx[k])}idx[k].dates.push(String(x.WORK_DATE).slice(0,10));idx[k].ids.push(String(x.LEAVE_ID))});const shiftVN={SANG:'Ca sáng',CHIEU:'Ca chiều',TOI:'Ca tối',NGAY:'Cả ngày'};l.innerHTML=groups.length?`<p class="ap-count"><b>${groups.length}</b> đơn chờ duyệt</p>`+groups.map(g=>`<article class="ap-card"><div class="ap-body"><div class="ap-row1"><b class="ap-name">${esc(g.x.EMPLOYEE_NAME)}</b><span class="ap-shift">${esc(shiftVN[String(g.x.SHIFT||g.x.TYPE).toUpperCase()]||g.x.SHIFT||g.x.TYPE||'')}</span></div><div class="ap-flags">${g.dates.sort().map(d=>`<span class="flag info">${esc(weekdayVN(d))} ${esc(formatVNDate(d))}</span>`).join('')}</div>${g.x.REASON?`<p class="lv-reason">“${esc(g.x.REASON)}”</p>`:''}<div class="ap-actions"><button type="button" class="btn ghost-red" data-lv="REJECTED" data-ids="${esc(g.ids.join(','))}">Từ chối</button><button type="button" class="btn green" data-lv="APPROVED" data-ids="${esc(g.ids.join(','))}">✓ Duyệt ${g.ids.length>1?g.ids.length+' ngày':''}</button></div></div></article>`).join(''):'<div class="empty big">✓ Không còn đơn nghỉ phép chờ duyệt.</div>'}
async function leaveDecision(ids,status){ids=(Array.isArray(ids)?ids:[ids]).map(String);ids.forEach(i=>LV.busy.add(i));renderLeaveApproval();try{const r=await api('adminLeaveDecision',{ids,STATUS:status});const bad=(r.results||[]).filter(x=>!x.ok);LV.rows=LV.rows.filter(x=>!ids.includes(String(x.LEAVE_ID))||bad.some(b=>String(b.id)===String(x.LEAVE_ID)));bad.forEach(b=>LV.busy.delete(String(b.id)));S.pending=Object.assign({},S.pending||{},{leave:Math.max(0,LV.rows.length)});toast(bad.length?'Chưa xử lý được: '+bad[0].error:(status==='APPROVED'?'Đã duyệt đơn nghỉ phép.':'Đã từ chối đơn nghỉ phép.'))}catch(e){ids.forEach(i=>LV.busy.delete(i));toast('Chưa lưu được: '+e.message)}if(screen==='admin:NGHỈ PHÉP')renderLeaveApproval()}

