// ===== V11.0.6: notifications, fast stats/history, reports + makeup =====
function dayShort(d){const w=['CN','T2','T3','T4','T5','T6','T7'][new Date(String(d).slice(0,10)+'T12:00:00+07:00').getUTCDay()];return w+' '+String(d).slice(8,10)+'/'+String(d).slice(5,7)}
function timeAgo(iso){const t=new Date(iso).getTime();if(!t)return '';const s=(Date.now()-t)/1000;if(s<60)return 'Vừa xong';if(s<3600)return Math.floor(s/60)+' phút trước';if(s<86400)return Math.floor(s/3600)+' giờ trước';const p=vietnamClockPartsAt(new Date(t)),hm=String(Math.floor(p.minute/60)).padStart(2,'0')+':'+String(p.minute%60).padStart(2,'0');return (s<172800?'Hôm qua':formatVNDate(p.date).slice(0,5))+' '+hm}
function lsGet(k){try{return JSON.parse(LS.getItem(k)||'null')}catch(_){return null}}
function lsSet(k,v){try{LS.setItem(k,JSON.stringify(v))}catch(_){}}
function isSystemNotice(n){return /LỖI HỆ THỐNG/i.test(String(n.TITLE||''))||/^(SYSTEM|ERROR)$/i.test(String(n.TYPE||''))||/processPushQueue|UrlFetchApp/i.test(String(n.MESSAGE||''))}
function within5Days(n){const t=new Date(n.CREATED_AT).getTime();return !t||Date.now()-t<=5*86400000}

// ---------- Notifications: newest first, collapsed preview, tap to expand, mark all ----------
async function renderNotifications(){screen='notifications';const isAdmin=me&&me.ROLE==='ADMIN';page(`<section class="screen wrap"><div class="nt-head"><button class="back" onclick="goBack()">← QUAY LẠI</button><button id="ntAll" class="btn light sm hidden" type="button">✓ Đã xem tất cả</button></div><h1 class="screen-title">THÔNG BÁO</h1><p class="helper">Thông báo trong 5 ngày gần nhất · bấm vào để xem chi tiết.</p>${isAdmin?'<button class="btn blue sm" type="button" onclick="adminNotifications()">✉ GỬI THÔNG BÁO CHO NHÂN VIÊN</button>':''}<div id="ntList" class="nt-list"></div></section>`);$('ntAll').onclick=markAllRead;$('ntList').addEventListener('toggle',e=>{const d=e.target;if(d.tagName!=='DETAILS')return;d.open?NT_OPEN.add(d.dataset.id):NT_OPEN.delete(d.dataset.id);if(d.open&&d.dataset.unread==='1')markOneRead(d.dataset.id,d)},true);drawNotifications();if(navigator.onLine){try{const j=await api('notificationsUser');S.notifications=(j.rows||[]);S.unread=S.notifications.filter(x=>!x.READ_AT);if(screen==='notifications')drawNotifications()}catch(e){}}}
const NT_OPEN=new Set(),NT_READ=new Set();
function drawNotifications(){const l=$('ntList');if(!l)return;(S.notifications||[]).forEach(n=>{if(NT_READ.has(String(n.NOTIFICATION_ID))&&!n.READ_AT)n.READ_AT=new Date().toISOString()});const rows=(S.notifications||[]).filter(within5Days).slice().sort((a,b)=>new Date(b.CREATED_AT)-new Date(a.CREATED_AT)),unread=rows.filter(n=>!n.READ_AT).length,all=$('ntAll');if(all)all.classList.toggle('hidden',!unread);if(all)all.textContent='✓ Đã xem tất cả ('+unread+')';l.innerHTML=rows.length?rows.map(n=>{const preview=n.TYPE==='ASSIGNMENT'?(n.TASK_TITLE||n.MESSAGE||''):(n.MESSAGE||'');return `<details ${NT_OPEN.has(String(n.NOTIFICATION_ID))?'open ':''}class="nt-item${n.READ_AT?'':' unread'}" data-id="${esc(n.NOTIFICATION_ID)}" data-unread="${n.READ_AT?0:1}"><summary><span class="nt-dot"></span><span class="nt-main"><b>${esc(n.TITLE||'THÔNG BÁO')}</b><span class="nt-prev">${esc(preview)}</span></span><small class="nt-time">${esc(timeAgo(n.CREATED_AT))}</small></summary><div class="nt-body">${n.TYPE==='ASSIGNMENT'?assignmentNoticeHTML(n)+'<button class="btn blue sm" type="button" onclick="renderWork()">XEM CÔNG VIỆC</button>':`<p class="notice-message">${esc(n.MESSAGE||'')}</p>`}</div></details>`}).join(''):'<div class="empty">Không có thông báo trong 5 ngày gần nhất.</div>'}
function markOneRead(id,el){NT_READ.add(String(id));const n=(S.notifications||[]).find(x=>String(x.NOTIFICATION_ID)===String(id));if(!n||n.READ_AT)return;n.READ_AT=new Date().toISOString();S.unread=(S.unread||[]).filter(x=>String(x.NOTIFICATION_ID)!==String(id));if(el){el.classList.remove('unread');el.dataset.unread='0'}const all=$('ntAll'),left=(S.notifications||[]).filter(x=>!x.READ_AT&&within5Days(x)).length;if(all){all.classList.toggle('hidden',!left);all.textContent='✓ Đã xem tất cả ('+left+')'}saveSnapshot(S);api('markNotificationRead',{NOTIFICATION_ID:id}).catch(()=>{})}
async function markAllRead(){const now=new Date().toISOString();(S.notifications||[]).forEach(n=>{NT_READ.add(String(n.NOTIFICATION_ID));if(!n.READ_AT)n.READ_AT=now});S.unread=[];saveSnapshot(S);drawNotifications();try{const j=await api('markAllNotificationsRead');toast('Đã đánh dấu '+(j.count||0)+' thông báo là đã xem.')}catch(e){toast('Chưa lưu được: '+e.message)}}
// Login popup: newest unread, max once per notice, never for system errors.
async function showUnread(){if(screen==='notifications')return;const shown=lsGet('cl_popped')||[],rows=(S.unread||[]).filter(n=>within5Days(n)&&!isSystemNotice(n)&&!shown.includes(String(n.NOTIFICATION_ID))).sort((a,b)=>new Date(b.CREATED_AT)-new Date(a.CREATED_AT));if(!rows.length)return;const n=rows[0];lsSet('cl_popped',shown.concat(String(n.NOTIFICATION_ID)).slice(-100));$('modalTitle').textContent='🔔 '+(n.TITLE||'THÔNG BÁO');$('modalText').innerHTML=n.TYPE==='ASSIGNMENT'?assignmentNoticeHTML(n):`<div class="notice-hero">${esc(n.MESSAGE||'')}</div>`;$('modalCancel').textContent='ĐÓNG';$('modalOk').textContent=rows.length>1?'XEM TẤT CẢ ('+rows.length+')':'ĐÃ XEM';$('modal').classList.remove('hidden');$('modalOk').onclick=()=>{$('modal').classList.add('hidden');markOneRead(n.NOTIFICATION_ID);if(rows.length>1)renderNotifications();else if(n.TYPE==='ASSIGNMENT')renderWork()};$('modalCancel').onclick=()=>{$('modal').classList.add('hidden')}}

// ---------- Employee stats/history: show cached data instantly, refresh in background ----------
async function loadStats(mode){const day=$('statsDate')?.value||localDate(),month=$('statsMonth')?.value||localMonth();if($('statsDateField'))$('statsDateField').style.display=mode==='DAY'?'block':'none';if($('statsMonthField'))$('statsMonthField').style.display=mode==='MONTH'?'block':'none';if($('statsDayBtn'))$('statsDayBtn').className=mode==='DAY'?'btn blue':'btn primary';if($('statsMonthBtn'))$('statsMonthBtn').className=mode==='MONTH'?'btn blue':'btn primary';const key='cl_stats_'+(me?.EMPLOYEE_ID||'')+'_'+(mode==='DAY'?day:month),area=$('statsArea');const cached=lsGet(key);if(cached&&area)drawStats(mode,cached,true);else if(area)area.innerHTML='<div class="loading-inline">Đang tải…</div>';try{const j=await api(mode==='DAY'?'dailyStats':'monthlyStats',mode==='DAY'?{date:day}:{month});lsSet(key,j);if(screen==='stats'&&($('statsDate')?.value||localDate())===day&&($('statsMonth')?.value||localMonth())===month)drawStats(mode,j,false)}catch(e){if(!cached&&area)area.textContent=e.message}}
function drawStats(mode,j,stale){const area=$('statsArea');if(!area)return;const note=stale?'<p class="helper stale">Đang cập nhật…</p>':'';if(mode==='DAY'){const rows=j.attendance||[];area.innerHTML=`${note}<div class="stats-summary"><span><b>${fmt2(j.summary?.workDays??rows.reduce((n,x)=>n+Number(x.WORK_DAYS||0),0))}</b><small>Công ngày</small></span><span><b>${fmt2(j.summary?.hours??0)}</b><small>Giờ làm</small></span></div><div class="stats-day"><h3>${esc(weekdayVN(j.date))}, ${esc(formatVNDate(j.date))}</h3>${rows.length?rows.map(statsShiftRow).join(''):'Không có ca làm được duyệt.'}</div>`}else{const g=j.grouped||[];area.innerHTML=`${note}<div class="stats-summary"><span><b>${fmt2(j.summary?.workDays??0)}</b><small>Công tháng ${esc(formatMonthVN(j.month))}</small></span><span><b>${fmt2(j.summary?.leave??0)}</b><small>Ngày phép</small></span><span><b>${j.summary?.late??0}</b><small>Đi muộn</small></span><span><b>${j.summary?.early??0}</b><small>Về sớm</small></span></div><div class="stats-month-detail">${g.length?g.slice().reverse().map(d=>`<details class="stats-day"><summary>${esc(dayShort(d.date))} · <b>${fmt2(d.rows.reduce((n,x)=>n+Number(x.WORK_DAYS||0),0))} công</b></summary>${d.rows.map(statsShiftRow).join('')}</details>`).join(''):'Chưa có ngày công được duyệt.'}</div>`}}
async function renderHistory(){screen='history';page(`<section class="screen wrap"><button class="back" onclick="goBack()">← QUAY LẠI</button><h1 class="screen-title">LỊCH SỬ CHẤM CÔNG</h1><p class="helper">60 ngày gần nhất.</p><div id="histList" class="ap-list"></div></section>`);const key='cl_hist2_'+(me?.EMPLOYEE_ID||''),cached=lsGet(key);if(cached)drawHistory(cached);else $('histList').innerHTML='<div class="loading-inline">Đang tải…</div>';try{const j=await api('userHistory');lsSet(key,j);if(screen==='history')drawHistory(j)}catch(e){if(!cached){const l=$('histList');if(l)l.innerHTML=`<div class="error-card">${esc(e.message)}</div>`}}}

// ---------- Reports ----------
const RP={tab:'DAY',date:'',month:'',year:0,emp:'ALL',onlyMissing:false,data:null,people:null,shifts:[],view:'main',detail:null};
const SHIFT_VN={SANG:'Sáng',CHIEU:'Chiều',TOI:'Tối',NGAY:'Cả ngày'};
function rpInit(){if(!RP.date)RP.date=localDate();if(!RP.month)RP.month=localMonth();if(!RP.year)RP.year=Number(localDate().slice(0,4))}
async function rpPeople(){if(RP.people)return RP.people;try{const j=await api('adminPeople');RP.people=(j.rows||[]).filter(x=>x.STATUS==='ACTIVE').sort((a,b)=>String(a.NAME).localeCompare(String(b.NAME),'vi'))}catch(_){RP.people=[]}return RP.people}
async function adminReports(){rpInit();RP.view='main';screen='reports';page(`<section class="screen wrap rp"><div class="rp-top"><button class="back sm" onclick="goBack()" aria-label="Quay lại">←</button><div class="seg" role="tablist">${[['DAY','NGÀY'],['MONTH','THÁNG'],['PROJECT','CÔNG TRÌNH']].map(([k,l])=>`<button type="button" role="tab" class="${RP.tab===k?'on':''}" data-tab="${k}">${l}</button>`).join('')}</div><button class="icon-sm" type="button" title="Xuất PDF / Excel" onclick="openExportMenu()">⤓</button></div><div id="rpFilters" class="rp-filters"></div><div id="rpBody" class="rp-body"></div></section>`);document.querySelector('.seg').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;RP.tab=b.dataset.tab;document.querySelectorAll('.seg button').forEach(x=>x.classList.toggle('on',x===b));renderRpFilters();loadRp()});$('rpBody').addEventListener('click',rpBodyClick);renderRpFilters();loadRp();rpPeople().then(()=>{if(screen==='reports'&&RP.tab!=='PROJECT')renderRpFilters()})}
function renderRpFilters(){const f=$('rpFilters');if(!f)return;const emp=`<select id="rpEmp" class="rp-sel" aria-label="Nhân viên"><option value="ALL">Tất cả NV</option>${(RP.people||[]).map(x=>`<option value="${esc(x.EMPLOYEE_ID)}" ${RP.emp===x.EMPLOYEE_ID?'selected':''}>${esc(x.NAME)}</option>`).join('')}</select>`;const y=Number(localDate().slice(0,4));if(RP.tab==='DAY')f.innerHTML=`<button type="button" class="step" data-step="-1">‹</button><input id="rpDate" type="date" value="${esc(RP.date)}" max="${localDate()}"><button type="button" class="step" data-step="1">›</button>${emp}`;else if(RP.tab==='MONTH')f.innerHTML=`<button type="button" class="step" data-step="-1">‹</button><input id="rpMonth" type="month" value="${esc(RP.month)}"><button type="button" class="step" data-step="1">›</button>${emp}`;else f.innerHTML=`<button type="button" class="step" data-step="-1">‹</button><select id="rpYear" class="rp-sel year" aria-label="Năm báo cáo">${[y+1,y,y-1,y-2,y-3,y-4].map(v=>`<option value="${v}" ${RP.year===v?'selected':''}>Năm ${v}</option>`).join('')}</select><button type="button" class="step" data-step="1">›</button>`;f.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>rpStep(Number(b.dataset.step)));const d=$('rpDate'),m=$('rpMonth'),yr=$('rpYear'),e=$('rpEmp');if(d)d.onchange=()=>{if(d.value){RP.date=d.value;loadRp()}};if(m)m.onchange=()=>{if(m.value){RP.month=m.value;loadRp()}};if(yr)yr.onchange=()=>{RP.year=Number(yr.value);loadRp()};if(e)e.onchange=()=>{RP.emp=e.value;loadRp()}}
function rpStep(n){if(RP.tab==='DAY'){const d=new Date(Date.parse(RP.date+'T12:00:00+07:00')+n*86400000),k=vietnamClockPartsAt(d).date;if(k>localDate())return;RP.date=k}else if(RP.tab==='MONTH'){let [y,m]=RP.month.split('-').map(Number);m+=n;if(m<1){m=12;y--}if(m>12){m=1;y++}RP.month=y+'-'+String(m).padStart(2,'0')}else RP.year+=n;renderRpFilters();loadRp()}
let rpSeq=0;
