function creditCls(v){return v>=1?'ok':v>0?'mid':'zero'}
function slotChips(items,leave,compact){const parts=(RP.shifts||[]).filter(s=>s.PART&&s.PART!=='NGAY');let h=parts.map(s=>{const it=items.find(i=>i.PART===s.PART)||items.find(i=>String(i.SHIFT_ID)===String(s.SHIFT_ID)),lab=compact?String(s.SHIFT_NAME).slice(0,1):s.SHIFT_NAME;if(!it)return `<span class="slot none">${esc(lab)} —</span>`;if(it.KIND==='MAKEUP')return `<span class="slot mk">${esc(lab)} · Bù</span>`;const t=it.IN?` ${it.IN}${compact?'':'–'+(it.OUT||'…')}`:'';return it.STATUS==='APPROVED'?`<span class="slot ok">${esc(lab)} ✓${esc(t)}</span>`:`<span class="slot pend">${esc(lab)} ⏳${esc(t)}</span>`}).join('');items.filter(i=>!parts.some(s=>s.PART===i.PART||String(s.SHIFT_ID)===String(i.SHIFT_ID))).forEach(i=>{h+=i.KIND==='MAKEUP'?`<span class="slot mk">${i.PART==='NGAY'?'Bù cả ngày':esc(i.SHIFT_NAME)+' · Bù'}</span>`:`<span class="slot ${i.STATUS==='APPROVED'?'ok':'pend'}">${esc(i.SHIFT_NAME)}</span>`});(leave||[]).forEach(l=>{h+=`<span class="slot leave">Phép ${esc(SHIFT_VN[l.SHIFT]||l.SHIFT)}${l.STATUS==='PENDING'?' (chờ)':''}</span>`});return h}
function drawRpDay(j){const body=$('rpBody'),rows=j.rows||[],missing=r=>r.WORK_DAYS+(r.LEAVE||[]).filter(l=>l.STATUS==='APPROVED').reduce((n,l)=>n+(l.SHIFT==='NGAY'?1:.5),0)<1;const nMiss=rows.filter(missing).length,view=RP.onlyMissing?rows.filter(missing):rows,s=j.summary||{};body.innerHTML=`<div class="rp-sum"><span><b>${fmt2(s.workDays)}</b> công</span><span><b>${s.withWork||0}/${s.employees||0}</b> NV có công</span>${s.pending?`<span class="warn"><b>${s.pending}</b> chờ duyệt</span>`:''}<button type="button" class="chip-f${RP.onlyMissing?' on':''}" data-miss="1">Thiếu công <span>${nMiss}</span></button></div><p class="rp-cap">${esc(weekdayVN(j.date))}, ${esc(formatVNDate(j.date))}</p>${view.map(r=>`<article class="rp-card"><div class="rp-row1"><button type="button" class="rp-name" data-emp="${esc(r.EMPLOYEE_ID)}" data-month="${esc(j.date.slice(0,7))}">${esc(r.NAME)} ›</button><span class="credit ${creditCls(r.WORK_DAYS)}">${fmt2(r.WORK_DAYS)} công</span></div><div class="slots">${slotChips(r.ITEMS||[],r.LEAVE)}</div>${r.WORK_DAYS<1.5?`<div class="rp-act"><button type="button" class="btn-mk" data-mk="${esc(r.EMPLOYEE_ID)}" data-date="${esc(j.date)}">+ Chấm bù</button></div>`:''}</article>`).join('')||'<div class="empty">Không có nhân viên phù hợp.</div>'}`}
