function drawRpProject(j){const body=$('rpBody'),rows=j.rows||[],s=j.summary||{},max=Math.max(1,...rows.map(r=>r.WORK_DAYS));body.innerHTML=`<div class="rp-sum"><span><b>${fmt2(s.workDays)}</b> công</span><span><b>${fmt2(s.hours)}</b> giờ</span><span><b>${s.projects||0}</b> CT có công</span></div><p class="rp-cap">Năm ${esc(String(j.year))} · bấm công trình để xem theo nhân viên</p>${rows.map(r=>`<button type="button" class="rp-line" data-proj="${esc(r.PROJECT_ID)}" data-pname="${esc(r.PROJECT_NAME)}"><span class="rp-line-main"><b>${esc(r.PROJECT_NAME)}</b><small>${fmt2(r.HOURS)} giờ · ${r.EMPLOYEES||0} nhân viên</small><span class="bar"><i style="width:${Math.round(r.WORK_DAYS/max*100)}%"></i></span></span><span class="credit big ${creditCls(r.WORK_DAYS)}">${fmt2(r.WORK_DAYS)}</span></button>`).join('')||'<div class="empty">Không có dữ liệu.</div>'}`}
