async function openEmpMonth(emp,month){RP.view='emp';RP.detail={emp,month};screen='reportEmp';page(`<section class="screen wrap rp"><div class="rp-top"><button class="back sm" onclick="adminReports()" aria-label="Về báo cáo">←</button><div class="rp-title" id="emTitle">Đang tải…</div><button class="icon-sm" type="button" title="Xuất PDF / Excel" onclick="openExportMenu()">⤓</button></div><div class="rp-filters"><button type="button" class="step" id="emPrev">‹</button><input id="emMonth" type="month" value="${esc(month)}"><button type="button" class="step" id="emNext">›</button></div><div id="emBody" class="rp-body"><div class="loading-inline">Đang tải…</div></div></section>`);const go=m=>openEmpMonth(emp,m),shift=n=>{let [y,mm]=month.split('-').map(Number);mm+=n;if(mm<1){mm=12;y--}if(mm>12){mm=1;y++}go(y+'-'+String(mm).padStart(2,'0'))};$('emPrev').onclick=()=>shift(-1);$('emNext').onclick=()=>shift(1);$('emMonth').onchange=e=>{if(e.target.value)go(e.target.value)};$('emBody').addEventListener('click',e=>{const b=e.target.closest('[data-mk]');if(!b)return;const day=(RP.detail.data?.grouped||[]).find(g=>g.date===b.dataset.date);openMakeup({employeeId:emp,name:RP.detail.data?.name||emp,date:b.dataset.date,items:day?day.rows:[],projectHint:RP.detail.lastProject,onDone:()=>openEmpMonth(emp,RP.detail.month)})});const ck='cl_rpe_'+emp+'_'+month,cached=lsGet(ck);if(cached){RP.detail.data=cached;if(cached.shifts)RP.shifts=cached.shifts;drawEmpMonth(cached)}try{const j=await api('adminEmployeeMonthDetail',{employeeId:emp,month});if(screen!=='reportEmp'||RP.detail.month!==month)return;lsSet(ck,j);RP.detail.data=j;if(j.shifts)RP.shifts=j.shifts;drawEmpMonth(j)}catch(e){$('emBody').innerHTML=`<div class="error-card">${esc(e.message)}</div>`}}
