const API_MEMO_TTL={adminPeople:120000,adminProjects:120000,adminEmployees:60000,adminShifts:60000,adminGroups:120000},apiMemo=new Map();

// ===== V11.0.9: history (compact by day, tap for details) + work list (5 days, newest first) =====
const PART_ORDER={SANG:1,CHIEU:2,TOI:3,NGAY:4};
function niceShift(v){v=String(v||'Ca');return v===v.toUpperCase()?v.charAt(0)+v.slice(1).toLocaleLowerCase('vi'):v}
function histFlags(x){const f=[];if(x.KIND==='MAKEUP'){f.push(['info','Công bổ sung do Admin ghi nhận'+(x.REASON?': '+x.REASON:'')]);return f}if(x.LATE)f.push(['warn','Vào trễ']);if(x.EARLY)f.push(['warn','Ra sớm']);const out=[];if(x.CHECKIN_GPS_STATUS==='OUTSIDE')out.push('vào ca'+(x.CHECKIN_DISTANCE_M!==null?' cách '+fmtDist(x.CHECKIN_DISTANCE_M):''));if(x.CHECKOUT_GPS_STATUS==='OUTSIDE')out.push('ra ca'+(x.CHECKOUT_DISTANCE_M!==null?' cách '+fmtDist(x.CHECKOUT_DISTANCE_M):''));if(out.length)f.push(['bad','Sai vị trí: '+out.join(', ')]);else if(x.IN&&(!x.CHECKIN_GPS_STATUS||x.CHECKIN_GPS_STATUS==='UNKNOWN'))f.push(['warn','Chưa xác minh vị trí']);if(x.DEVICE)f.push(['warn','Giờ điện thoại lệch']);if(x.IN&&!x.OUT&&x.STATUS!=='REJECTED')f.push(['info','Chưa ra ca']);if(x.STATUS==='REJECTED'&&x.REJECT_REASON)f.push(['bad','Lý do từ chối: '+x.REJECT_REASON]);return f}
function drawHistory(j){const l=$('histList');if(!l)return;const rows=j.rows||[];if(rows.length&&!('PART'in rows[0])){l.innerHTML='<div class="loading-inline">Đang tải…</div>';return}const days={};rows.forEach(x=>(days[x.WORK_DATE]||(days[x.WORK_DATE]=[])).push(x));const keys=Object.keys(days).sort().reverse();if(!keys.length){l.innerHTML='<div class="empty">Chưa có lượt chấm công nào trong 60 ngày.</div>';return}
  l.innerHTML=keys.map(d=>{const it=days[d].slice().sort((a,b)=>(PART_ORDER[a.PART]||9)-(PART_ORDER[b.PART]||9)||String(a.IN).localeCompare(String(b.IN))),credit=it.reduce((n,x)=>n+Number(x.WORK_DAYS||0),0),hours=it.reduce((n,x)=>n+Number(x.HOURS||0),0),mark=it.some(x=>x.STATUS==='REJECTED'||histFlags(x).some(f=>f[0]==='bad'))?'bad':it.some(x=>x.STATUS==='PENDING'||histFlags(x).some(f=>f[0]==='warn'))?'warn':'';
    const line=x=>`<div class="hline"><span class="hshift">${esc(niceShift(x.SHIFT_NAME))}</span> <span class="hproj">(${esc(x.PROJECT_NAME||'—')})</span>${x.KIND==='MAKEUP'?' <span class="hmk">· công bù</span>':` · vào <b>${esc(x.IN||'—')}</b> · ra <b>${esc(x.OUT||'—')}</b>`}</div>`;
    const det=x=>`<div class="hdet"><div class="hdet-top"><b>${esc(niceShift(x.SHIFT_NAME))}</b>${statusBadge(x.STATUS==='BỔ SUNG'?'APPROVED':x.STATUS)}${Number(x.HOURS)>=0.01?`<span class="hhours">${fmt2(x.HOURS)} giờ</span>`:''}</div>${histFlags(x).map(f=>`<span class="flag ${f[0]}">${esc(f[1])}</span>`).join('')||'<span class="flag ok">✓ Đúng giờ, đúng vị trí</span>'}</div>`;
    return `<details class="hday"><summary><div class="hday-head"><span class="hday-date">${esc(weekdayVN(d))}, ${esc(formatVNDate(d))}</span>${mark?`<span class="hmark ${mark}"></span>`:''}<span class="credit ${creditCls(credit)}">${fmt2(credit)} công</span></div>${it.map(line).join('')}</summary><div class="hbody">${it.map(det).join('')}<div class="htotal">Tổng giờ làm trong ngày: <b>${fmt2(hours)} giờ</b> · Công đã duyệt: <b>${fmt2(credit)}</b></div></div></details>`}).join('')}
function renderWork(refresh=true){screen='work';const today=localDate(),from=vnDateOffset(today,-4),rows=(S.assignments||[]).filter(x=>String(x.WORK_DATE||'').slice(0,10)>=from).slice().sort((a,b)=>(new Date(b.CREATED_AT||0)-new Date(a.CREATED_AT||0))||String(b.WORK_DATE).localeCompare(String(a.WORK_DATE))),when=d=>{d=String(d).slice(0,10);return d===today?'Hôm nay':d===vnDateOffset(today,1)?'Ngày mai':d===vnDateOffset(today,-1)?'Hôm qua':weekdayVN(d)+', '+formatVNDate(d)};page(`<section class="screen wrap"><button class="back" onclick="goBack()">← QUAY LẠI</button><h1 class="screen-title">CÔNG VIỆC</h1><p class="helper">Công việc được giao trong 5 ngày gần nhất · mới nhất ở trên.</p><div class="ap-list">${rows.length?rows.map(x=>{const fresh=x.CREATED_AT&&Date.now()-new Date(x.CREATED_AT).getTime()<86400000,st=clockText(x.START_TIME),en=clockText(x.END_TIME);return `<article class="work-card${String(x.WORK_DATE).slice(0,10)<today?' past':''}"><div class="ap-row1"><span class="work-when">${esc(when(x.WORK_DATE))}</span>${fresh?'<span class="badge warn">MỚI</span>':''}</div><b class="work-title">${esc(x.TASK_TITLE||'Công việc')}</b><div class="ap-proj">${esc(x.PROJECT_NAME||projectName(x.PROJECT_ID))}</div><div class="ap-time"><span>Ca <b>${esc(x.SHIFT_NAME||shiftName(x.SHIFT_ID))}</b>${st&&en?` · ${esc(st)}–${esc(en)}`:''}</span></div>${x.NOTE?`<p class="work-note">${esc(x.NOTE)}</p>`:''}</article>`}).join(''):'<div class="empty">Không có công việc được giao trong 5 ngày gần nhất.</div>'}</div></section>`);if(refresh&&navigator.onLine&&Date.now()-lastBootAt>15000)bootstrap().then(()=>{if(screen==='work')renderWork(false)}).catch(e=>toast(e.message))}
// ===== V11.0.11: admin notifications & logs (instant open, select/delete), auto IDs =====
function nextCode(rows,col,prefix){let max=0,w=3;const re=new RegExp('^'+prefix+'(\\d+)$','i');(rows||[]).forEach(x=>{const m=String(x[col]||'').trim().match(re);if(m){max=Math.max(max,Number(m[1]));w=Math.max(w,m[1].length)}});return prefix+String(max+1).padStart(w,'0')}
function fmtDT(iso){const t=new Date(iso);if(isNaN(t))return String(iso||'');const p=vietnamClockPartsAt(t);return formatVNDate(p.date).slice(0,5)+' '+String(Math.floor(p.minute/60)).padStart(2,'0')+':'+String(p.minute%60).padStart(2,'0')}
function delBar(n,sel,kind){return `<label class="sel-all"><input type="checkbox" data-${kind}all ${n&&sel===n?'checked':''} ${n?'':'disabled'}> Chọn tất cả (${n})</label><button type="button" class="btn red sm" data-${kind}del ${sel?'':'disabled'}>🗑 Xóa${sel?' '+sel:''}</button>`}
// ---- Notifications (send + manage) ----
const NTA={rows:[],sel:new Set()};
async function adminNotifications(){adminShell('THÔNG BÁO',`<details class="card nf-card"><summary><b>✉ Gửi thông báo mới</b></summary><div class="field"><label>Nhân viên</label><select id="nf_emp"><option value="">Đang tải danh sách…</option></select></div><div class="field"><label>Tiêu đề</label><input id="nf_title"></div><div class="field"><label>Nội dung</label><textarea id="nf_msg"></textarea></div><button class="btn blue full" onclick="sendAdminNotif()">GỬI THÔNG BÁO</button></details><div class="del-bar" id="ntaBar"></div><div id="ntaList" class="ap-list"><div class="loading-inline">Đang tải…</div></div>`);const root=document.querySelector('#app .screen');root.addEventListener('click',ntaClick);root.addEventListener('change',e=>{const d=e.target.dataset||{};if(d.nid){e.target.checked?NTA.sel.add(d.nid):NTA.sel.delete(d.nid);drawNta(false)}else if('ntall'in d){NTA.sel=e.target.checked?new Set(NTA.rows.map(x=>String(x.NOTIFICATION_ID))):new Set();drawNta()}});NTA.sel.clear();const cached=lsGet('cl_adm_nt');if(cached){NTA.rows=cached;drawNta()}api('adminPeople').then(e=>{const s=$('nf_emp');if(s)s.innerHTML=(e.rows||[]).filter(x=>x.STATUS==='ACTIVE').map(x=>`<option value="${esc(x.EMPLOYEE_ID)}">${esc(x.NAME)}</option>`).join('')}).catch(()=>{});try{const j=await api('adminNotifications');NTA.rows=j.rows||[];lsSet('cl_adm_nt',NTA.rows.slice(0,150));if(screen==='admin:THÔNG BÁO')drawNta()}catch(e){if(!cached){const l=$('ntaList');if(l)l.innerHTML=`<div class="error-card">${esc(e.message)}</div>`}}}
function drawNta(list=true){const bar=$('ntaBar');if(bar)bar.innerHTML=delBar(NTA.rows.length,NTA.sel.size,'nt');if(!list)return;const l=$('ntaList');if(!l)return;l.innerHTML=NTA.rows.length?NTA.rows.map(n=>{const id=String(n.NOTIFICATION_ID);return `<label class="del-row${NTA.sel.has(id)?' on':''}"><input type="checkbox" data-nid="${esc(id)}" ${NTA.sel.has(id)?'checked':''}><span class="del-main"><b>${esc(n.TITLE||'THÔNG BÁO')}</b><small>${esc(n.EMPLOYEE_NAME||n.EMPLOYEE_ID||'')} · ${esc(fmtDT(n.CREATED_AT))} · ${n.READ_AT?'Đã xem':'<span class="unread-t">Chưa xem</span>'}</small><span class="del-msg">${esc(n.MESSAGE||'')}</span></span></label>`}).join(''):'<div class="empty">Không có thông báo.</div>'}
async function ntaClick(e){const t=e.target.closest('[data-ntdel]');if(!t||t.disabled)return;const ids=[...NTA.sel];confirmBox('Xóa '+ids.length+' thông báo đã chọn? Không thể khôi phục.','XÓA',async()=>{const keep=NTA.rows;NTA.rows=NTA.rows.filter(x=>!NTA.sel.has(String(x.NOTIFICATION_ID)));NTA.sel.clear();drawNta();try{const r=await api('adminDeleteNotifications',{ids});lsSet('cl_adm_nt',NTA.rows.slice(0,150));toast('Đã xóa '+r.deleted+' thông báo.')}catch(err){NTA.rows=keep;drawNta();toast('Chưa xóa được: '+err.message)}})}
// ---- Logs ----
const LGA={rows:[],sel:new Set(),total:0};
async function adminLogs(){adminShell('NHẬT KÝ',`<div class="section-actions compact"><button class="btn light sm" onclick="runAdminDataAudit()">KIỂM TRA ĐỘ NHẤT QUÁN</button><button class="btn light sm" onclick="downloadApiTiming()">XUẤT NHẬT KÝ TỐC ĐỘ</button></div><div id="dataAuditArea"></div><p class="helper" id="lgaInfo"></p><div class="del-bar" id="lgaBar"></div><div id="lgaList" class="ap-list"><div class="loading-inline">Đang tải…</div></div>`);const root=document.querySelector('#app .screen');root.addEventListener('click',lgaClick);root.addEventListener('change',e=>{const d=e.target.dataset||{};if(d.lrow){e.target.checked?LGA.sel.add(d.lrow):LGA.sel.delete(d.lrow);drawLga(false)}else if('lgall'in d){LGA.sel=e.target.checked?new Set(LGA.rows.map(x=>String(x.ROW))):new Set();drawLga()}});LGA.sel.clear();const cached=lsGet('cl_adm_lg');if(cached){LGA.rows=cached.rows||[];LGA.total=cached.total||0;drawLga()}await loadLga()}
async function loadLga(){try{const j=await api('adminLogs');LGA.rows=j.rows||[];LGA.total=j.total||LGA.rows.length;LGA.sel.clear();lsSet('cl_adm_lg',{rows:LGA.rows.slice(0,150),total:LGA.total});if(screen==='admin:NHẬT KÝ')drawLga()}catch(e){toast(e.message)}}
function drawLga(list=true){const info=$('lgaInfo');if(info)info.textContent=`Sheet NHẬT KÝ có ${LGA.total} dòng · hiển thị ${LGA.rows.length} dòng mới nhất.`;const bar=$('lgaBar');if(bar)bar.innerHTML=delBar(LGA.rows.length,LGA.sel.size,'lg');if(!list)return;const l=$('lgaList');if(!l)return;l.innerHTML=LGA.rows.length?LGA.rows.map(x=>{const k=String(x.ROW);return `<label class="del-row log${LGA.sel.has(k)?' on':''}"><input type="checkbox" data-lrow="${esc(k)}" ${LGA.sel.has(k)?'checked':''}><span class="del-main"><span class="log-top"><span class="log-act">${esc(x.ACTION)}</span><small>${esc(fmtDT(x.TIME))} · ${esc(x.USER_ID)}</small></span><span class="del-msg">${esc(x.DETAIL)}</span></span></label>`}).join(''):'<div class="empty">Nhật ký trống.</div>'}
async function lgaClick(e){const t=e.target.closest('[data-lgdel]');if(!t||t.disabled)return;const items=LGA.rows.filter(x=>LGA.sel.has(String(x.ROW))).map(x=>({row:x.ROW,time:x.TIME,action:x.ACTION}));confirmBox('Xóa '+items.length+' dòng nhật ký đã chọn? Không thể khôi phục.','XÓA',async()=>{const keep=LGA.rows;LGA.rows=LGA.rows.filter(x=>!LGA.sel.has(String(x.ROW)));LGA.sel.clear();drawLga();try{const r=await api('adminDeleteLogs',{items});toast('Đã xóa '+r.deleted+' dòng nhật ký'+(r.skipped?' ('+r.skipped+' dòng đã thay đổi, bỏ qua)':'')+'.');await loadLga()}catch(err){LGA.rows=keep;drawLga();toast('Chưa xóa được: '+err.message)}})}
// ===== V11.0.12: install prompt (Android) / guide (iPhone), Android back button, shortcuts =====
let installEvt=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvt=e;renderInstallBanner()});
window.addEventListener('appinstalled',()=>{installEvt=null;lsSet('cl_installed',1);renderInstallBanner()});
function isAndroid(){return /Android/i.test(navigator.userAgent)}
function installState(){if(isStandalone()||lsGet('cl_installed'))return 'installed';if(installEvt)return 'android';if(isIOS())return 'ios';return 'none'}
function renderInstallBanner(){const b=$('installBanner');if(!b)return;const st=installState(),snooze=Number(lsGet('cl_install_snooze')||0),show=(st==='android'||st==='ios')&&Date.now()>snooze;b.classList.toggle('hidden',!show);if(show)b.innerHTML=`<span>📲 ${st==='ios'?'Thêm app vào Màn hình chính để mở nhanh, toàn màn hình và nhận thông báo.':'Cài app lên điện thoại để mở nhanh như ứng dụng thật.'}</span><button type="button" class="btn blue sm" onclick="installApp()">${st==='ios'?'HƯỚNG DẪN':'CÀI APP'}</button><button type="button" class="ib-x" aria-label="Để sau" onclick="snoozeInstall()">✕</button>`}
function snoozeInstall(){lsSet('cl_install_snooze',Date.now()+7*86400000);renderInstallBanner()}
async function installApp(){if(installEvt){const e=installEvt;installEvt=null;try{e.prompt();const r=await e.userChoice;if(r&&r.outcome==='accepted')lsSet('cl_installed',1)}catch(_){}renderInstallBanner();return}if(isIOS())confirmBox('1. Mở trang này bằng Safari.\n2. Bấm nút Chia sẻ (ô vuông có mũi tên ↑).\n3. Chọn "Thêm vào MH chính" → Thêm.\n4. Mở app từ biểu tượng CHẤM CÔNG ngoài màn hình chính.','ĐÃ HIỂU',()=>{})}
// Android back button / iOS edge swipe: go back inside the app instead of closing it.
const HOME_SCREENS=['userHome','adminHome','login','changePassword',''];
let navGuard=false;
function navAfterRender(){try{if(!token||HOME_SCREENS.includes(screen))return;if(!(history.state&&history.state.app))history.pushState({app:1},'')}catch(_){}}
window.addEventListener('popstate',()=>{if(!token)return;const sheet=document.querySelector('.sheet-bg');if(sheet){sheet.remove();navAfterRender();return}if(!$('modal').classList.contains('hidden')){$('modal').classList.add('hidden');navAfterRender();return}if(HOME_SCREENS.includes(screen))return;if(screen==='reportEmp'||screen==='reportProj'){adminReports();return}goBack()});
// Home-screen shortcuts (Android long-press): ?go=attendance|history|work|approve|reports
let shortcutDone=false;
function runShortcut(){if(shortcutDone||!me)return;shortcutDone=true;const go=new URLSearchParams(location.search).get('go');if(!go)return;try{history.replaceState(history.state,'',location.pathname)}catch(_){}const map=me.ROLE==='ADMIN'?{approve:adminAttendance,reports:adminReports}:{attendance:()=>renderAttendance(),history:renderHistory,work:()=>renderWork()};if(map[go])setTimeout(map[go],50)}
window.renderUserHome=renderUserHome;window.renderAttendance=renderAttendance;window.renderOtherAttendance=renderOtherAttendance;window.checkinOther=checkinOther;window.openNotification=openNotification;window.renderStats=renderStats;window.loadStats=loadStats;window.renderWork=renderWork;window.renderLeave=renderLeave;window.renderNotifications=renderNotifications;window.renderHistory=renderHistory;window.doLogout=doLogout;window.requestLogout=requestLogout;window.checkin=checkin;window.checkout=checkout;window.requestDayAttendance=requestDayAttendance;window.renderAttendanceShiftState=renderAttendanceShiftState;window.addLeaveDate=addLeaveDate;window.removeLeaveDate=removeLeaveDate;window.sendLeave=sendLeave;window.readNotif=readNotif;window.adminDashboard=adminDashboard;window.adminEmployees=adminEmployees;window.employeeForm=employeeForm;window.saveEmployee=saveEmployee;window.adminProjects=adminProjects;window.projectForm=projectForm;window.saveProject=saveProject;window.adminShifts=adminShifts;window.toggleShiftCard=toggleShiftCard;window.saveShiftRow=saveShiftRow;window.shiftForm=shiftForm;window.toggleShiftFormFields=toggleShiftFormFields;window.saveShift=saveShift;window.adminAttendance=adminAttendance;window.approveAttendance=approveAttendance;window.adminMakeup=adminMakeup;window.saveMakeup=saveMakeup;window.adminGroups=adminGroups;window.groupForm=groupForm;window.saveGroup=saveGroup;window.adminAssignments=adminAssignments;window.saveAssignment=saveAssignment;window.deleteAssignment=deleteAssignment;window.adminLeave=adminLeave;window.leaveDecision=leaveDecision;window.adminNotifications=adminNotifications;window.sendAdminNotif=sendAdminNotif;window.adminReports=adminReports;window.loadReport=loadReport;window.backToEmployeeReport=()=>{if($('rp_emp'))$('rp_emp').value='ALL';loadReport()};window.syncReportDateField=syncReportDateField;window.refreshProjectReportOptions=refreshProjectReportOptions;window.downloadCSV=downloadCSV;window.adminLogs=adminLogs;window.runAdminDataAudit=runAdminDataAudit;window.downloadApiTiming=downloadApiTiming;window.changePassword=changePassword;window.goBack=goBack;window.resetAndSync=resetAndSync;window.installApp=installApp;window.snoozeInstall=snoozeInstall;window.openExportMenu=openExportMenu;window.enablePush=enablePush;window.loadRp=loadRp;window.openEmpMonth=openEmpMonth;window.gpsRetry=gpsRetry;
